package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1qynsu9dwj9lq0m5fkje7jh6qy3md80ztqnshhm"), 1),
		},
		"Add validator g1qynsu9dwj9lq0m5fkje7jh6qy3md80ztqnshhm",
		"Add operator g1qynsu9dwj9lq0m5fkje7jh6qy3md80ztqnshhm to the active valset with voting power 1.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

package ambassadorweek

import "strconv"

var count int

func Increment(_ realm) int {
	count++
	return count
}

func Render(path string) string {
	return "# Sapphire Ambassador Smoke Test\n\nCount: " + strconv.Itoa(count)
}

package ambassadorweek

import "testing"

func TestIncrement(cur realm, t *testing.T) {
	value := Increment(cross(cur))
	if value != 1 {
		t.Fatalf("expected 1, got %d", value)
	}
}

